@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Playfair+Display:wght@600;700;800;900&display=swap');
:root{--ink:#121722;--navy:#101a2a;--navy2:#17283d;--gold:#e7bb67;--gold2:#f6d991;--paper:#f6f1e8;--muted:#a9b0ba;--red:#e5484d;--teal:#4ca99b;--panel:#111a27;--line:rgba(231,187,103,.5)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:#0d1119;color:var(--paper);font-family:Manrope,system-ui,sans-serif}body{overflow:hidden}.game-shell{height:100dvh;min-height:600px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 30%,#273750 0,#121b2a 55%,#0d1119 100%)}button{font:inherit;color:inherit;cursor:pointer}.intro-screen{position:absolute;inset:0;display:grid;place-items:center;overflow:hidden;background:radial-gradient(ellipse at 50% 44%,#233148 0,#141d2b 45%,#090d14 100%);z-index:10}.intro-screen:before,.intro-screen:after{content:"";position:absolute;inset:0;pointer-events:none}.intro-screen:before{background:linear-gradient(90deg,transparent 49.8%,rgba(231,187,103,.09) 50%,transparent 50.2%),linear-gradient(0deg,transparent 49.8%,rgba(231,187,103,.07) 50%,transparent 50.2%);background-size:95px 95px;mask-image:radial-gradient(ellipse,#000,transparent 70%)}.intro-screen:after{background:linear-gradient(0deg,#090d14 0,transparent 38%,rgba(9,13,20,.1));}.intro-grain{position:absolute;inset:-50%;opacity:.11;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E")}.intro-content{position:relative;z-index:2;width:min(760px,88vw);text-align:center;display:flex;align-items:center;flex-direction:column}.eyebrow,.intro-note,.intro-subtitle,.top-center,.hp-copy,.scene-caption,.speaker-row,.dialogue-footer,.typing-kicker,.no-timer,.target-quote>span,.typing-footer,.bottom-bar,.hallway-sign,.judge-dais .dais-front{font-family:'DM Mono',monospace;letter-spacing:.13em}.eyebrow{font-size:10px;color:var(--gold);margin:0 0 20px}.intro-content h1{font:900 clamp(76px,15vw,150px)/.8 'Playfair Display',serif;letter-spacing:-.08em;margin:0;color:#f6f1e8;text-shadow:0 12px 40px #0008}.intro-content h1 span,.wordmark span,.typing-heading h2 span{color:var(--gold)}.intro-subtitle{font-size:12px;letter-spacing:.52em;margin:22px 0 24px;color:#c5c8cd}.intro-rule{width:72px;height:1px;background:var(--gold);margin:0 0 25px}.synopsis{font:500 clamp(15px,2.1vw,19px)/1.9 Manrope,sans-serif;color:#d9dce0;max-width:680px;min-height:175px;margin:0 0 24px}.gold-button{border:1px solid var(--gold);background:linear-gradient(110deg,#ddae56,#f1d38f);color:#171a20;font:800 12px 'DM Mono',monospace;letter-spacing:.1em;padding:16px 27px;box-shadow:0 8px 32px #0005;transition:.2s}.gold-button:hover{transform:translateY(-2px);box-shadow:0 12px 35px #d5ab5b44}.gold-button span{font-size:17px;margin-left:20px}.intro-note{font-size:9px;color:#89909c;margin-top:27px;letter-spacing:.25em}.intro-seal{position:absolute;right:8vw;bottom:8vh;width:90px;height:90px;border:1px solid #e7bb673b;border-radius:50%;display:grid;place-content:center;text-align:center;color:#e7bb6780;font:800 28px 'Playfair Display';transform:rotate(-12deg)}.intro-seal span{font-size:12px}
.courtroom{height:100%;max-width:1600px;margin:auto;display:flex;flex-direction:column;padding:0 clamp(12px,3vw,48px);position:relative}.topbar{height:64px;flex:none;display:grid;grid-template-columns:1fr 2fr 1fr;align-items:center;border-bottom:1px solid #ffffff15;position:relative;z-index:3}.wordmark{font:800 23px 'Playfair Display';letter-spacing:-.08em;color:#f6f1e8;text-decoration:none}.top-center{font-size:9px;color:#aab1be;text-align:center;letter-spacing:.11em}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#d7ad60;box-shadow:0 0 10px #d7ad60;margin:0 9px 1px 0}.hp-panel{justify-self:end;width:min(180px,30vw)}.hp-copy{display:flex;justify-content:space-between;font-size:9px;color:#bbc1cc;margin-bottom:6px}.hp-copy strong{color:var(--gold2);font-weight:500}.hp-track{height:5px;border:1px solid #e7bb6744;background:#090e15}.hp-fill{height:100%;width:100%;background:linear-gradient(90deg,#d34c47,#f1b668);transition:width .8s cubic-bezier(.2,.8,.2,1)}.scene-wrap{flex:1;min-height:190px;position:relative;padding:15px 0 0}.scene{height:100%;position:relative;min-height:230px;overflow:hidden;border:1px solid #d5ad673b;background:linear-gradient(180deg,#26354a 0,#46536a 47%,#6b5543 48%,#36271f 100%);isolation:isolate;box-shadow:0 14px 42px #0006}.scene:before{content:"";position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(90deg,#10172370,transparent 20%,transparent 80%,#10172370),linear-gradient(0deg,#10131bcc,transparent 34%,#141c2b30)}.court-glow{position:absolute;width:60%;height:72%;left:20%;top:-10%;background:radial-gradient(ellipse,#edd8a435 0,transparent 68%)}.window{position:absolute;top:7%;width:16%;height:42%;border:5px solid #3a302b;background:linear-gradient(180deg,#89aab7,#d1bc8e);box-shadow:inset 0 0 0 2px #cba965,0 8px 16px #0005}.window:before{content:"";position:absolute;top:0;bottom:0;left:48%;width:5px;background:#57473a}.window:after{content:"";position:absolute;left:0;right:0;top:48%;height:5px;background:#57473a}.window-left{left:7%}.window-right{right:7%}.window i,.window b{position:absolute;z-index:1;bottom:-13px;left:-9px;right:-9px;height:10px;background:#49392f}.wall-seal{position:absolute;top:6%;left:50%;transform:translateX(-50%);width:80px;height:80px;border:2px solid #d3b3688a;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-direction:column;color:#e8c77d;text-shadow:0 2px #53402c}.wall-seal span{font-size:24px}.wall-seal small{font:8px 'DM Mono';letter-spacing:.16em}.balcony{position:absolute;top:47%;height:8%;width:100%;background:linear-gradient(180deg,#947247,#503a2a 25%,#493423);border-top:3px solid #c09b5f;border-bottom:5px solid #211d1b;box-shadow:0 10px 20px #0008}.judge-dais{position:absolute;z-index:2;top:7%;left:50%;width:20%;height:51%;transform:translateX(-50%);display:flex;align-items:center;flex-direction:column}.judge-figure{height:76%;width:45%;position:relative;display:flex;align-items:center;flex-direction:column}.judge-wig{position:absolute;top:0;z-index:2;width:85%;height:37%;border-radius:48% 48% 40% 40%;background:radial-gradient(circle at 23% 38%,#fff 0 11%,#d1d1cb 13% 17%,transparent 19%),radial-gradient(circle at 74% 34%,#fff 0 12%,#d4d4d0 15% 19%,transparent 21%),radial-gradient(circle at 50% 18%,#fff 0 13%,#d3d2cb 16% 20%,transparent 22%),#eeece4;filter:drop-shadow(0 3px 2px #2228)}.judge-face{position:absolute;z-index:1;top:21%;width:55%;height:45%;border-radius:43% 43% 48% 48%;background:#c88e6e}.judge-face .brow{position:absolute;top:35%;left:16%;width:68%;height:4px;background:#47352d;transform:rotate(-4deg)}.judge-face .eye{position:absolute;top:44%;left:28%;width:45%;height:3px;background:#242129}.judge-face .beard{position:absolute;bottom:-20%;left:8%;width:84%;height:42%;background:#eeeae0;clip-path:polygon(5% 0,95% 0,78% 79%,50% 100%,22% 79%)}.judge-robe{position:absolute;bottom:0;width:100%;height:40%;background:linear-gradient(90deg,#241d2a,#591e26 18%,#8d2932 50%,#571e28 82%,#211b25);clip-path:polygon(30% 0,70% 0,100% 100%,0 100%)}.dais-front{position:absolute;bottom:0;width:100%;height:24%;background:linear-gradient(180deg,#9a7242,#593b25);border-top:3px solid #d2ad68;box-shadow:0 7px 10px #0005;display:grid;place-items:center;font-size:7px;color:#f4d18c}.bench{position:absolute;z-index:2;top:53%;width:30%;height:30%;background:linear-gradient(180deg,#392c28,#4e3329 55%,#231d1c);border-top:4px solid #bc9456;box-shadow:0 8px 13px #0007}.bench-left{left:6%}.bench-right{right:6%}.bench:before{content:"";position:absolute;top:-24%;height:24%;left:12%;right:12%;background:linear-gradient(180deg,#694a32,#2a2424);border-top:3px solid #bb9459}.bench-front{position:absolute;inset:auto 0 0;height:39%;display:grid;place-items:center;border-top:1px solid #c59d5d55;color:#d9b675;font:7px 'DM Mono';letter-spacing:.2em}.wood-floor{position:absolute;bottom:0;width:100%;height:24%;background:repeating-linear-gradient(90deg,transparent 0 11%,#b28b5933 11.2% 11.5%),linear-gradient(0deg,#1e1a1b,#604633);border-top:1px solid #bc965c}.rail{position:absolute;z-index:3;top:69%;height:5px;width:34%;background:linear-gradient(180deg,#d8b772,#72512f);box-shadow:0 3px 5px #0008}.rail:after{content:"";position:absolute;top:4px;left:7%;right:7%;height:40px;background:repeating-linear-gradient(90deg,#9d7745 0 3px,transparent 3px 18%)}.rail-left{left:0}.rail-right{right:0}.hallway-sign{position:absolute;z-index:4;right:2%;top:3%;font-size:7px;color:#fff;letter-spacing:.12em;display:none}.hallway-sign b{display:block;color:var(--gold2);margin-top:4px}.scene-caption{position:absolute;z-index:4;bottom:10px;left:14px;right:14px;display:flex;justify-content:space-between;font-size:8px;color:#d4d2cc;letter-spacing:.12em;text-shadow:0 2px 3px #000}.character{position:absolute;z-index:3;bottom:12%;width:17%;height:60%;min-width:100px;max-width:200px;filter:drop-shadow(0 9px 8px #0006);transform-origin:bottom center;transition:opacity .4s,filter .4s,transform .4s;--skin:#d29a77;--hair:#182032;--coat:#172333}.character:after{content:attr(data-character);position:absolute;bottom:-12px;left:50%;transform:translateX(-50%);font:8px 'DM Mono';letter-spacing:.12em;color:#f3e7d2;text-shadow:0 2px 3px #000;white-space:nowrap}.character-rudy{left:13%;--coat:#172738;--skin:#d49b7b;--hair:#101c30}.character-kalista{right:13%;--coat:#242536;--skin:#d29a7a}.character-raya{right:14%;--coat:#3b2d32;--skin:#bd8264;--hair:#19191b;display:none}.character-setot{right:15%;--coat:#355044;--skin:#bd896d;display:none}.char-aura{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 50%,#eac56c2e,transparent 68%);opacity:0}.character.active{transform:translateY(-3px) scale(1.05);filter:drop-shadow(0 0 12px #f1ca7850) drop-shadow(0 9px 8px #0007)}.character.active .char-aura{opacity:1}.char-body{position:absolute;bottom:0;left:8%;width:84%;height:54%;background:linear-gradient(90deg,#111926,var(--coat) 27%,var(--coat) 70%,#111722);clip-path:polygon(27% 0,73% 0,100% 100%,0 100%);border-radius:25% 25% 0 0}.char-neck{position:absolute;top:42%;left:42%;width:16%;height:12%;background:var(--skin)}.char-head{position:absolute;top:13%;left:24%;width:52%;height:39%;border-radius:45% 45% 40% 40%;background:linear-gradient(90deg,#a96e58,var(--skin) 25% 75%,#a76d56);box-shadow:inset 0 -7px 8px #7044322b}.char-head .eyes{position:absolute;top:50%;left:15%;right:15%;display:flex;justify-content:space-between}.eyes i{width:23%;height:4px;background:#28212a;border-radius:50%;transform:rotate(-4deg)}.char-head .nose{position:absolute;top:56%;left:48%;width:4px;height:8px;border-right:1px solid #8e5d4c}.char-head .mouth{position:absolute;left:39%;top:75%;width:25%;height:3px;background:#723a3d;border-radius:50%}.character-rudy .hair{position:absolute;top:-8%;left:-6%;width:110%;height:44%;background:linear-gradient(145deg,#172e4f,#10192c 70%);clip-path:polygon(0 58%,10% 12%,27% 35%,37% 0,48% 31%,67% 5%,72% 33%,100% 8%,91% 79%,80% 53%,71% 75%,59% 55%,49% 79%,34% 53%,20% 81%)}.character-rudy .hair-fringe{position:absolute;top:-1%;left:0;width:90%;height:46%;background:#152c4b;clip-path:polygon(0 0,100% 0,78% 62%,60% 41%,50% 100%,33% 48%,15% 78%)}.character-rudy .char-body:after{content:"";position:absolute;top:3%;left:36%;width:27%;height:34%;background:#ede7da;clip-path:polygon(0 0,100% 0,70% 100%,50% 82%,28% 100%)}.character-rudy .tie{position:absolute;top:5%;left:48%;width:9%;height:40%;background:#ba3942;clip-path:polygon(0 0,100% 0,72% 100%,50% 85%,27% 100%)}.character-kalista .char-body{background:linear-gradient(90deg,#1b1b2b,#343247 48%,#1d1e2d)}.character-kalista .hijab{position:absolute;top:-14%;left:-19%;width:139%;height:117%;border-radius:48% 48% 35% 35%;background:linear-gradient(135deg,#252639,#171a28 58%,#323247);clip-path:polygon(21% 0,78% 0,97% 49%,82% 100%,50% 90%,16% 100%,1% 48%)}.character-kalista .hijab-inner{position:absolute;top:-2%;left:10%;width:80%;height:91%;border-radius:46% 46% 42% 42%;border:2px solid #5b5769;border-bottom:0}.character-kalista .char-head{z-index:1;height:37%;top:23%}.character-kalista .char-neck{z-index:1;top:50%}.character-kalista .char-coat{position:absolute;inset:0;background:linear-gradient(90deg,#222235,#393447,#1b1d2b);clip-path:polygon(27% 0,73% 0,100% 100%,0 100%)}.character-raya .hair{position:absolute;top:-7%;left:-4%;width:108%;height:37%;background:linear-gradient(170deg,#28252a,#101115);clip-path:polygon(0 45%,10% 0,73% 0,100% 38%,81% 75%,66% 40%,23% 51%)}.character-raya .char-body:after{content:"";position:absolute;top:4%;left:35%;width:30%;height:32%;background:#ddd8cb;clip-path:polygon(0 0,100% 0,65% 100%,50% 84%,33% 100%)}.character-raya .tie{position:absolute;top:6%;left:48%;width:9%;height:42%;background:#683744;clip-path:polygon(0 0,100% 0,72% 100%,50% 85%,27% 100%)}.character-setot .char-body{background:linear-gradient(90deg,#25372f,#436253,#24372f)}.character-setot .batik{position:absolute;inset:2% 27%;background:repeating-linear-gradient(45deg,transparent 0 7px,#e6c46b99 8px 9px,transparent 10px 15px);opacity:.7}.character-setot .hair{position:absolute;top:-3%;left:8%;width:84%;height:19%;background:#40352e;border-radius:50% 50% 10% 10%}.character-setot .mouth{width:28%;left:36%}.character-raya,.character-setot{right:13%}.character-raya:after,.character-setot:after{bottom:-12px}
.objection-flash{position:absolute;inset:0;z-index:8;display:flex;align-items:center;justify-content:center;flex-direction:column;background:#080b13df;opacity:0;pointer-events:none;transform:scale(1.3);transition:opacity .22s,transform .22s}.objection-flash.show{opacity:1;transform:scale(1)}.objection-flash:before,.objection-flash:after{content:"";position:absolute;inset:18% -20%;background:linear-gradient(165deg,transparent 35%,#d22c37 35% 41%,#f4d284 41% 43%,transparent 43%);transform:rotate(-9deg)}.objection-flash:after{transform:rotate(9deg);opacity:.6}.objection-streaks{position:absolute;inset:0;background:repeating-linear-gradient(172deg,transparent 0 42px,#fff1 43px 45px,transparent 46px 88px);mix-blend-mode:screen}.objection-flash strong{z-index:1;font:900 clamp(40px,10vw,110px)/.9 'Playfair Display';font-style:italic;letter-spacing:-.06em;color:#fff;text-shadow:5px 5px 0 #b81727,-3px -3px 0 #d9b567,0 0 35px #fff8;transform:skew(-10deg)}.objection-flash strong span{color:#f3cd73}.objection-flash small{z-index:1;font:10px 'DM Mono';letter-spacing:.3em;margin-top:22px;color:#f4dcaa}
.dialogue-panel{flex:none;position:relative;margin:12px 0 0;min-height:133px;max-height:28vh;border:3px solid var(--gold);background:linear-gradient(115deg,#171f2d,#101721);box-shadow:0 7px 30px #0007,inset 0 0 0 1px #fff1;display:flex;flex-direction:column;padding:11px 17px 8px}.speaker-row{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e7bb673d;padding-bottom:7px}.speaker-name{font-size:10px;font-weight:500;color:var(--gold2);letter-spacing:.15em}.dialogue-hint{font-size:8px;color:#747f8e}.dialogue-text{overflow-y:auto;overscroll-behavior:contain;scrollbar-color:#b9914d #1c2633;scrollbar-width:thin;padding:10px 7px 7px 0;flex:1;min-height:50px;font-size:clamp(13px,1.3vw,16px);line-height:1.75;color:#f1eee8;white-space:pre-wrap}.dialogue-text::-webkit-scrollbar,.typing-mirror::-webkit-scrollbar{width:7px}.dialogue-text::-webkit-scrollbar-thumb,.typing-mirror::-webkit-scrollbar-thumb{background:#b9914d;border-radius:9px}.dialogue-footer{font-size:8px;color:#808997;display:flex;justify-content:space-between;align-items:center}.sound-indicator{font-style:normal;color:var(--gold);font-size:12px;margin-right:5px}.continue-button{border:0;background:transparent;color:var(--gold2);font:10px 'DM Mono';letter-spacing:.1em;padding:3px}.continue-button b{font-size:15px;margin-left:10px}.typing-panel{flex:none;margin:12px 0 0;border:1px solid #d7b05e;background:linear-gradient(115deg,#151e2b,#101620);padding:12px 16px 11px;box-shadow:0 9px 24px #0007}.typing-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:7px}.typing-kicker{font-size:8px;color:var(--gold);letter-spacing:.16em}.typing-heading h2{font:700 19px 'Playfair Display';margin:3px 0 0}.no-timer{font-size:8px;color:#a4aab3;border:1px solid #ffffff20;padding:6px 8px;white-space:nowrap}.target-quote{max-height:92px;overflow-y:auto;scrollbar-width:thin;scrollbar-color:#b9914d #1c2633;border-left:2px solid #b68b49;padding:5px 10px;margin-bottom:9px;background:#ffffff06}.target-quote>span{display:block;font-size:7px;color:#9b8a6c;margin-bottom:3px}.target-quote p{font-size:12px;line-height:1.55;color:#e9dfca;margin:0}.input-wrap{position:relative;height:66px;background:#0b111a;border:1px solid #49515d;overflow:hidden}.typing-mirror,.input-wrap textarea{position:absolute;inset:0;width:100%;height:100%;margin:0;padding:9px 11px;font:500 13px/1.6 Manrope,sans-serif;letter-spacing:.01em;white-space:pre-wrap;overflow:auto;overflow-wrap:anywhere;word-break:normal;border:0;resize:none;scrollbar-width:thin;scrollbar-color:#b9914d #1c2633}.typing-mirror{pointer-events:none;color:#f1eadd}.typing-mirror .correct{color:#f1eadd}.typing-mirror .incorrect{color:#ff696d;text-decoration:underline wavy #ff696d;text-underline-offset:2px}.typing-mirror .extra{color:#ff696d}.input-wrap textarea{z-index:2;background:transparent;color:transparent;caret-color:#f6cd78;outline:0}.input-wrap textarea::selection{background:#f6cd7840}.input-placeholder{position:absolute;top:9px;left:11px;color:#6e7785;font-size:12px;pointer-events:none}.input-wrap.has-value .input-placeholder{display:none}.typing-footer{display:flex;justify-content:space-between;align-items:center;margin-top:8px;font-size:8px;color:#a6acb4;letter-spacing:.04em}.submit-button{background:#d8b565;color:#171a20;border:0;padding:9px 12px;font:800 9px 'DM Mono';letter-spacing:.08em;transition:.2s}.submit-button:disabled{opacity:.42;cursor:not-allowed}.submit-button b{margin-left:8px;font-size:14px}.bottom-bar{height:35px;flex:none;display:flex;align-items:center;justify-content:space-between;color:#747f8b;font-size:8px;letter-spacing:.1em}.bottom-bar i{color:var(--gold);font-style:normal;padding:0 5px}.bottom-bar button{border:0;background:transparent;font:8px 'DM Mono';letter-spacing:.1em;color:#858d98;padding:5px}.bottom-bar button b{color:#ddbd73;margin-left:5px}.toast{position:absolute;z-index:20;bottom:56px;left:50%;transform:translate(-50%,10px);opacity:0;transition:.25s;background:#2c1c22;border:1px solid #d05858;color:#ffd9d6;padding:10px 14px;font:10px 'DM Mono';max-width:90vw;text-align:center;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.end-screen{position:absolute;z-index:12;inset:0;background:#080c13eF;display:grid;place-items:center;padding:20px}.end-card{max-width:600px;text-align:center;padding:clamp(25px,6vw,55px);border:1px solid #d7b665;background:linear-gradient(145deg,#202c3b,#101620);box-shadow:0 20px 70px #000b}.end-card h2{font:800 clamp(40px,8vw,72px)/1 'Playfair Display';letter-spacing:-.04em;margin:15px 0}.end-card h2 em{font-weight:600;color:var(--gold2)}.end-card p{color:#d1d4d7;line-height:1.8;font-size:14px}.ending-values{display:flex;justify-content:center;gap:14px;color:var(--gold);font:9px 'DM Mono';letter-spacing:.13em;margin:23px 0}.courtroom.hallway .scene{background:linear-gradient(90deg,#303343,#7c6d62 48%,#303343);}.courtroom.hallway .scene:before{background:linear-gradient(90deg,#121726aa,transparent 24%,transparent 76%,#121726aa),linear-gradient(0deg,#10131bcc,transparent 35%)}.courtroom.hallway .window,.courtroom.hallway .balcony,.courtroom.hallway .judge-dais,.courtroom.hallway .bench,.courtroom.hallway .wall-seal{display:none}.courtroom.hallway .hallway-sign{display:block}.courtroom.hallway .wood-floor{height:17%}.courtroom.hallway .character{bottom:11%}
